    n = ct.loc[mask, 'Mã đơn hàng'].nunique()
    return r0(rev / n) if n else 0


def orders(mask):
    return int(ct.loc[mask, 'Mã đơn hàng'].nunique())


def sl_numeric(s):
    m = re.search(r'\d+', str(s))
    return float(m.group()) if m else 1.0


