    sub = ct[(ct['dt'].dt.normalize() == d) & (ct['name_n'] == _h_norm(name))]
    row = sub.iloc[0]
    factor = float(row['slqd']) / sl_numeric(row['Số lượng'])
    return r0(float(_h_money(row['Đơn giá'])) / (factor if factor else 1.0))

